package com.jinloes.practice;
import java.util.*;
public class Solution { public static class TreeNode { public int value; public TreeNode left; public TreeNode right; public TreeNode(int value){this.value=value;} public TreeNode(int value, TreeNode left, TreeNode right){this.value=value;this.left=left;this.right=right;} } public record TraversalOrders(List<Integer> preorder,List<Integer> inorder,List<Integer> postorder){} public static TraversalOrders traversalOrders(TreeNode root){List<Integer> a=new ArrayList<>(),b=new ArrayList<>(),c=new ArrayList<>(); v(root,a,b,c); return new TraversalOrders(a,b,c);} private static void v(TreeNode n,List<Integer>a,List<Integer>b,List<Integer>c){if(n==null)return; a.add(n.value); v(n.left,a,b,c); b.add(n.value); v(n.right,a,b,c); c.add(n.value);} }
